import bundled from '../data/calendar.json';
import {
  MS_MINUTE,
  type OffsetTable,
  formatDate,
  instantsOfLocal,
  isoWeekday,
  makeOffsetTable,
  parseDate,
  parseIsoUtc,
} from './time';

export type EventKind = 'fomc' | 'cpi' | 'nfp' | 'opex' | 'roll';
export const EVENT_KINDS: readonly EventKind[] = ['fomc', 'cpi', 'nfp', 'opex', 'roll'];
export const EVENT_LABEL: Record<EventKind, string> = { fomc: 'FOMC', cpi: 'CPI', nfp: 'NFP', opex: 'OPEX', roll: 'Roll' };

export interface CalendarJson {
  schema: 'algolift.setup-odds.calendar/1';
  version: string;
  sources: Record<string, { file: string; version: number; sha256: string }>;
  timezone: 'America/New_York';
  coverage: { start: string; end: string };
  session: {
    class: string;
    open: string;
    close: string;
    opensPreviousDay: boolean;
    rth: { open: string; close: string };
    weekends: boolean;
  };
  closures: Record<string, string>;
  earlyCloses: Record<string, { rule: string; close: string }>;
  undecided: Record<string, string>;
  events: {
    kinds: Record<
      string,
      { label: string; coverage: { start: string; end: string }; releaseTimeEt: string | null; provenance: string }
    >;
    dates: { kind: string; dateEt: string; tradingDay: string | null; label: string; provenance: string }[];
  };
  utcOffsets: Record<string, [string, number][]>;
  offsetRange: { start: string; end: string };
}

export interface MappedEvent {
  kind: EventKind;
  dateEt: string;
  tradingDay: string;
  /** trading-day index of tradingDay */
  idx: number;
}

/** A loaded calendar. Treat every field except `json` and `version` as internal. */
export interface Calendar {
  readonly json: CalendarJson;
  readonly version: string;
  readonly coverageStart: number;
  readonly coverageEnd: number;
  /** trading days (day numbers), ascending; their position is the trading-day index */
  readonly days: Int32Array;
  readonly indexOfDay: Map<number, number>;
  /** session minute of each trading day's close */
  readonly close: Int32Array;
  readonly earlyClose: Uint8Array;
  /** number of trading days with regular hours before each index */
  readonly rthBefore: Int32Array;
  /** indices of trading days with regular hours */
  readonly rthDays: Int32Array;
  /** instant of session minute 0 of each trading day */
  readonly base: Float64Array;
  readonly ny: OffsetTable;
  readonly chicago: OffsetTable;
  /** per kind: sorted unique trading-day indices of its event days */
  readonly eventDays: Record<EventKind, Int32Array>;
  /** per kind: coverage as day numbers */
  readonly eventCoverage: Record<EventKind, [number, number]>;
  readonly mappedEvents: MappedEvent[];
}

export class CalendarError extends Error {
  readonly code: 'K_SCHEMA' | 'K_VERSION' | 'K_TABLE';
  constructor(code: 'K_SCHEMA' | 'K_VERSION' | 'K_TABLE', message: string) {
    super(message);
    this.name = 'CalendarError';
    this.code = code;
  }
}

const SCHEMA = 'algolift.setup-odds.calendar/1';
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

function schemaFail(msg: string): never {
  throw new CalendarError('K_SCHEMA', msg);
}

function dateOrFail(s: unknown, what: string): number {
  if (typeof s !== 'string') schemaFail(`${what} is not a date`);
  const d = parseDate(s);
  if (d === null) schemaFail(`${what} is not a date: ${s}`);
  return d;
}

function table(rows: unknown, zone: string, start: number, end: number): OffsetTable {
  if (!Array.isArray(rows) || rows.length === 0) throw new CalendarError('K_TABLE', `utcOffsets.${zone} is missing`);
  const out: [number, number][] = [];
  for (const r of rows) {
    if (!Array.isArray(r) || r.length !== 2 || typeof r[0] !== 'string' || !Number.isInteger(r[1]))
      throw new CalendarError('K_TABLE', `utcOffsets.${zone} has a malformed entry`);
    const t = parseIsoUtc(r[0]);
    if (t === null) throw new CalendarError('K_TABLE', `utcOffsets.${zone} has a bad instant ${r[0]}`);
    if (out.length && t <= out[out.length - 1][0]) throw new CalendarError('K_TABLE', `utcOffsets.${zone} is not ascending`);
    out.push([t, r[1] as number]);
  }
  if (out[0][0] !== start) throw new CalendarError('K_TABLE', `utcOffsets.${zone} does not start at offsetRange.start`);
  if (out[out.length - 1][0] >= end) throw new CalendarError('K_TABLE', `utcOffsets.${zone} runs past offsetRange.end`);
  return makeOffsetTable(out, start, end);
}

/** Validate and index a calendar in the `algolift.setup-odds.calendar/1` schema. Throws CalendarError. */
export function loadCalendar(json: unknown): Calendar {
  if (!isObj(json)) schemaFail('the calendar is not a JSON object');
  if (typeof json.schema !== 'string') schemaFail('the calendar has no schema');
  if (json.schema !== SCHEMA) {
    if (json.schema.startsWith('algolift.setup-odds.calendar/'))
      throw new CalendarError('K_VERSION', `calendar schema ${json.schema} is not ${SCHEMA}`);
    schemaFail(`${json.schema} is not a Setup Odds calendar`);
  }
  const j = json as unknown as CalendarJson;
  if (typeof j.version !== 'string') schemaFail('version is missing');
  if (!isObj(j.coverage)) schemaFail('coverage is missing');
  const covStart = dateOrFail(j.coverage.start, 'coverage.start');
  const covEnd = dateOrFail(j.coverage.end, 'coverage.end');
  if (covEnd < covStart) schemaFail('coverage ends before it starts');
  const s = j.session;
  if (
    !isObj(s) ||
    s.class !== 'futures_cme_equity' ||
    s.open !== '18:00' ||
    s.close !== '17:00' ||
    s.opensPreviousDay !== true ||
    !isObj(s.rth) ||
    s.rth.open !== '09:30' ||
    s.rth.close !== '16:00' ||
    s.weekends !== false
  )
    schemaFail('session must be futures_cme_equity, 18:00 to 17:00, regular hours 09:30 to 16:00, no weekends');
  for (const k of ['closures', 'earlyCloses', 'undecided'] as const) if (!isObj(j[k])) schemaFail(`${k} is missing`);
  for (const [d, v] of Object.entries(j.earlyCloses)) {
    dateOrFail(d, 'an earlyCloses date');
    if (!isObj(v) || typeof v.rule !== 'string' || typeof v.close !== 'string' || !TIME_RE.test(v.close))
      schemaFail(`earlyCloses.${d} is malformed`);
  }
  for (const d of Object.keys(j.closures)) dateOrFail(d, 'a closures date');
  for (const d of Object.keys(j.undecided)) dateOrFail(d, 'an undecided date');
  if (!isObj(j.events) || !isObj(j.events.kinds) || !Array.isArray(j.events.dates)) schemaFail('events is missing');
  if (!isObj(j.offsetRange)) throw new CalendarError('K_TABLE', 'offsetRange is missing');
  const rStart = parseIsoUtc(String(j.offsetRange.start));
  const rEnd = parseIsoUtc(String(j.offsetRange.end));
  if (rStart === null || rEnd === null || rEnd <= rStart) throw new CalendarError('K_TABLE', 'offsetRange is malformed');
  if (!isObj(j.utcOffsets)) throw new CalendarError('K_TABLE', 'utcOffsets is missing');
  const ny = table(j.utcOffsets['America/New_York'], 'America/New_York', rStart, rEnd);
  const chicago = table(j.utcOffsets['America/Chicago'], 'America/Chicago', rStart, rEnd);

  // trading days
  const dayList: number[] = [];
  const closeList: number[] = [];
  const earlyList: number[] = [];
  for (let d = covStart; d <= covEnd; d++) {
    const wd = isoWeekday(d);
    if (wd > 5) continue;
    const key = isoKey(d);
    if (key in j.closures || key in j.undecided) continue;
    dayList.push(d);
    const ec = j.earlyCloses[key];
    if (ec) {
      const [h, mi] = ec.close.split(':').map(Number);
      closeList.push((h * 60 + mi - 1080 + 1440) % 1440);
      earlyList.push(1);
    } else {
      closeList.push(1380);
      earlyList.push(0);
    }
  }
  const n = dayList.length;
  const days = Int32Array.from(dayList);
  const close = Int32Array.from(closeList);
  const earlyClose = Uint8Array.from(earlyList);
  const indexOfDay = new Map<number, number>();
  dayList.forEach((d, i) => indexOfDay.set(d, i));
  const rthBefore = new Int32Array(n);
  const rthList: number[] = [];
  for (let i = 0; i < n; i++) {
    rthBefore[i] = rthList.length;
    if (close[i] > 930) rthList.push(i);
  }
  const base = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    // session minute 0 is 18:00 on the calendar day before D
    const local = (days[i] - 1) * 86400000 + 1080 * MS_MINUTE;
    const inst = instantsOfLocal(ny, local);
    if (!inst || inst.length !== 1) throw new CalendarError('K_TABLE', `the offset table does not cover the session of ${isoKey(days[i])}`);
    base[i] = inst[0];
  }

  // events
  const eventCoverage = {} as Record<EventKind, [number, number]>;
  for (const k of EVENT_KINDS) {
    const kind = j.events.kinds[k];
    if (!isObj(kind) || !isObj(kind.coverage)) schemaFail(`events.kinds.${k} is missing`);
    eventCoverage[k] = [dateOrFail(kind.coverage.start, `events.kinds.${k}.coverage.start`), dateOrFail(kind.coverage.end, `events.kinds.${k}.coverage.end`)];
  }
  const sets: Record<EventKind, Set<number>> = { fomc: new Set(), cpi: new Set(), nfp: new Set(), opex: new Set(), roll: new Set() };
  const mappedEvents: MappedEvent[] = [];
  for (const e of j.events.dates) {
    if (!isObj(e) || typeof e.kind !== 'string' || typeof e.dateEt !== 'string') schemaFail('an events.dates entry is malformed');
    if (!(EVENT_KINDS as readonly string[]).includes(e.kind)) continue;
    if (e.tradingDay === null) continue;
    const td = dateOrFail(e.tradingDay, 'an event tradingDay');
    const idx = indexOfDay.get(td);
    if (idx === undefined) schemaFail(`event tradingDay ${e.tradingDay} is not a trading day`);
    sets[e.kind as EventKind].add(idx);
    if (e.tradingDay !== e.dateEt) mappedEvents.push({ kind: e.kind as EventKind, dateEt: e.dateEt, tradingDay: e.tradingDay, idx });
  }
  const eventDays = {} as Record<EventKind, Int32Array>;
  for (const k of EVENT_KINDS) eventDays[k] = Int32Array.from([...sets[k]].sort((a, b) => a - b));

  return {
    json: j,
    version: j.version,
    coverageStart: covStart,
    coverageEnd: covEnd,
    days,
    indexOfDay,
    close,
    earlyClose,
    rthBefore,
    rthDays: Int32Array.from(rthList),
    base,
    ny,
    chicago,
    eventDays,
    eventCoverage,
    mappedEvents,
  };
}

const isoKey = (d: number): string => formatDate(d);

let cached: Calendar | null = null;

/** The bundled data/calendar.json, parsed once. */
export function defaultCalendar(): Calendar {
  if (!cached) cached = loadCalendar(bundled as unknown);
  return cached;
}

/** The trading-day index of a day number, or -1. */
export function tradingIndex(cal: Calendar, day: number): number {
  const i = cal.indexOfDay.get(day);
  return i === undefined ? -1 : i;
}

/** min(1320, close): the end of regular hours, in session minutes (<= 930 means none). */
export function rthClose(cal: Calendar, idx: number): number {
  const c = cal.close[idx];
  return c < 1320 ? c : 1320;
}

export function hasRth(cal: Calendar, idx: number): boolean {
  return cal.close[idx] > 930;
}

/** Index of the k-th prior session (trading days with regular hours) before idx, or -1. */
export function priorSession(cal: Calendar, idx: number, k: number): number {
  const pos = cal.rthBefore[idx] - k;
  return pos >= 0 ? cal.rthDays[pos] : -1;
}
